Index: test/OrderedArrayTest.java
===================================================================
--- test/OrderedArrayTest.java	
+++ test/OrderedArrayTest.java	
@@ -0,0 +1,214 @@
+public class OrderedArrayTest {
+    public static void main(String[] args) {
+        testConstructor();
+        testInsert();
+        testInsertAutoResize();
+        testInsertMaintainsOrder();
+        testFind();
+        testFindNotFound();
+        testDelete();
+        testDeleteNotFound();
+        testGet();
+        testGetIndexOutOfBounds();
+        testSize();
+        testCount();
+        testResize();
+        testResizeShrink();
+        testDeleteThenInsert();
+        testEmptyArray();
+        testInsertDuplicates();
+        testFindEdgeCases();
+        System.out.println("All OrderedArrayTest tests passed!");
+    }
+
+    static void testConstructor() {
+        OrderedArray oa = new OrderedArray(5);
+        assert oa.size() == 5 : "size should be 5";
+        assert oa.count() == 0 : "count should be 0 after construction";
+    }
+
+    static void testInsert() {
+        OrderedArray oa = new OrderedArray(5);
+        oa.insert(30);
+        oa.insert(10);
+        oa.insert(20);
+        assert oa.count() == 3 : "count should be 3 after three inserts";
+        assert oa.find(10) == 0 : "10 should be at index 0";
+        assert oa.find(20) == 1 : "20 should be at index 1";
+        assert oa.find(30) == 2 : "30 should be at index 2";
+    }
+
+    static void testInsertAutoResize() {
+        OrderedArray oa = new OrderedArray(2);
+        oa.insert(2);
+        oa.insert(1);
+        assert oa.size() == 2 : "size should still be 2 before overflow";
+        oa.insert(3);
+        assert oa.size() == 4 : "size should have doubled to 4";
+        assert oa.count() == 3 : "count should be 3 after resize and insert";
+        assert oa.find(1) != -1 : "1 should be found";
+        assert oa.find(2) != -1 : "2 should be found";
+        assert oa.find(3) != -1 : "3 should be found";
+    }
+
+    static void testInsertMaintainsOrder() {
+        OrderedArray oa = new OrderedArray(10);
+        oa.insert(5);
+        oa.insert(1);
+        oa.insert(3);
+        oa.insert(2);
+        oa.insert(4);
+        assert oa.find(1) == 0 : "1 should be at index 0";
+        assert oa.find(2) == 1 : "2 should be at index 1";
+        assert oa.find(3) == 2 : "3 should be at index 2";
+        assert oa.find(4) == 3 : "4 should be at index 3";
+        assert oa.find(5) == 4 : "5 should be at index 4";
+    }
+
+    static void testFind() {
+        OrderedArray oa = new OrderedArray(5);
+        oa.insert(10);
+        oa.insert(20);
+        oa.insert(30);
+        assert oa.find(10) == 0 : "10 should be at index 0";
+        assert oa.find(20) == 1 : "20 should be at index 1";
+        assert oa.find(30) == 2 : "30 should be at index 2";
+    }
+
+    static void testFindNotFound() {
+        OrderedArray oa = new OrderedArray(3);
+        oa.insert(10);
+        oa.insert(30);
+        assert oa.find(20) == -1 : "20 (between 10 and 30) should not be found";
+        assert oa.find(5) == -1 : "5 (below min) should not be found";
+        assert oa.find(50) == -1 : "50 (above max) should not be found";
+    }
+
+    static void testDelete() {
+        OrderedArray oa = new OrderedArray(5);
+        oa.insert(10);
+        oa.insert(20);
+        oa.insert(30);
+        assert oa.delete(20) : "delete should return true for existing element";
+        assert oa.count() == 2 : "count should be 2 after deletion";
+        assert oa.find(20) == -1 : "20 should no longer be found";
+        assert oa.find(10) == 0 : "10 should still be at index 0";
+        assert oa.find(30) == 1 : "30 should now be at index 1 after shift";
+    }
+
+    static void testDeleteNotFound() {
+        OrderedArray oa = new OrderedArray(3);
+        oa.insert(1);
+        assert !oa.delete(99) : "delete should return false for non-existent element";
+        assert oa.count() == 1 : "count should remain 1";
+    }
+
+    static void testGet() {
+        OrderedArray oa = new OrderedArray(5);
+        oa.insert(42);
+        try {
+            assert oa.get(0) == 42 : "get(0) should return 42";
+        } catch (IndexOutOfBoundsException e) {
+            assert false : "get(0) should not throw";
+        }
+    }
+
+    static void testGetIndexOutOfBounds() {
+        OrderedArray oa = new OrderedArray(3);
+        oa.insert(1);
+        boolean caught = false;
+        try {
+            oa.get(-1);
+        } catch (IndexOutOfBoundsException e) {
+            caught = true;
+        }
+        assert caught : "get(-1) should throw IndexOutOfBoundsException";
+        caught = false;
+        try {
+            oa.get(5);
+        } catch (IndexOutOfBoundsException e) {
+            caught = true;
+        }
+        assert caught : "get(5) should throw IndexOutOfBoundsException";
+    }
+
+    static void testSize() {
+        OrderedArray oa = new OrderedArray(10);
+        assert oa.size() == 10 : "size should be 10";
+        oa.resize(20);
+        assert oa.size() == 20 : "size should be 20 after resize";
+    }
+
+    static void testCount() {
+        OrderedArray oa = new OrderedArray(5);
+        assert oa.count() == 0 : "count should be 0 initially";
+        oa.insert(1);
+        oa.insert(2);
+        assert oa.count() == 2 : "count should be 2";
+        oa.delete(1);
+        assert oa.count() == 1 : "count should be 1 after delete";
+    }
+
+    static void testResize() {
+        OrderedArray oa = new OrderedArray(3);
+        oa.insert(100);
+        oa.insert(200);
+        oa.resize(5);
+        assert oa.size() == 5 : "size should be 5";
+        assert oa.count() == 2 : "count should still be 2";
+        assert oa.find(100) != -1 : "100 should still be found";
+        assert oa.find(200) != -1 : "200 should still be found";
+        assert oa.get(0) == 100 : "get(0) should be 100";
+        assert oa.get(1) == 200 : "get(1) should be 200";
+    }
+
+    static void testResizeShrink() {
+        OrderedArray oa = new OrderedArray(10);
+        oa.insert(1);
+        oa.insert(2);
+        oa.insert(3);
+        oa.resize(2);
+        assert oa.size() == 2 : "size should be 2";
+        assert oa.count() == 2 : "count should be clamped to 2";
+        assert oa.find(1) != -1 : "1 should still be found";
+        assert oa.find(2) != -1 : "2 should still be found";
+        assert oa.find(3) == -1 : "3 should be discarded";
+    }
+
+    static void testDeleteThenInsert() {
+        OrderedArray oa = new OrderedArray(5);
+        oa.insert(10);
+        oa.insert(30);
+        oa.delete(10);
+        oa.insert(20);
+        assert oa.count() == 2 : "count should be 2";
+        assert oa.find(20) != -1 : "20 should be found";
+        assert oa.find(30) != -1 : "30 should be found";
+    }
+
+    static void testEmptyArray() {
+        OrderedArray oa = new OrderedArray(3);
+        assert oa.find(1) == -1 : "find on empty array should return -1";
+        assert !oa.delete(1) : "delete on empty array should return false";
+        assert oa.count() == 0 : "count should be 0";
+    }
+
+    static void testInsertDuplicates() {
+        OrderedArray oa = new OrderedArray(5);
+        oa.insert(5);
+        oa.insert(5);
+        oa.insert(5);
+        assert oa.count() == 3 : "count should be 3 with duplicates";
+        assert oa.find(5) != -1 : "5 should be found";
+    }
+
+    static void testFindEdgeCases() {
+        OrderedArray oa = new OrderedArray(5);
+        oa.insert(1);
+        assert oa.find(1) == 0 : "finding the only element should return index 0";
+        oa.insert(2);
+        assert oa.find(2) == 1 : "finding last element should work";
+        assert oa.find(0) == -1 : "finding below min should return -1";
+        assert oa.find(3) == -1 : "finding above max should return -1";
+    }
+}

