public class UnorderedArrayTest {
    public static void main(String[] args) {
        testConstructor();
        testConstructorSizeZero();
        testInsert();
        testInsertAtEnd();
        testInsertAutoResize();
        testInsertMultipleAfterResize();
        testFind();
        testFindFirstOccurrenceDuplicates();
        testFindNotFound();
        testFindOnEmptyArray();
        testDeleteFirstElement();
        testDeleteLastElement();
        testDeleteOnlyElement();
        testDeleteNotFound();
        testDeleteFromEmptyArray();
        testDeleteMultipleInSequence();
        testGet();
        testGetNullPosition();
        testGetIndexOutOfBoundsNegative();
        testGetIndexOutOfBoundsLarge();
        testGetIndexAtCapacity();
        testSize();
        testCount();
        testCountAfterMultipleDeletes();
        testResizeExpand();
        testResizeShrink();
        testResizeToZero();
        testResizeToZeroThenInsert();
        testResizePreserveOrder();
        testResizeLargerThenSmaller();
        testDeleteThenInsert();
        testInsertAfterDeleteFillsGap();
        testEmptyArray();
        testFullArrayInsertTriggersResize();
        testUnsortedProperty();
        System.out.println("All UnorderedArrayTest tests passed!");
    }

    // --- Constructor ---

    static void testConstructor() {
        UnorderedArray ua = new UnorderedArray(5);
        assert ua.size() == 5 : "size should be 5";
        assert ua.count() == 0 : "count should be 0 after construction";
    }

    static void testConstructorSizeZero() {
        UnorderedArray ua = new UnorderedArray(0);
        assert ua.size() == 0 : "size should be 0";
        assert ua.count() == 0 : "count should be 0";
    }

    // --- Insert ---

    static void testInsert() {
        UnorderedArray ua = new UnorderedArray(3);
        ua.insert(10);
        assert ua.count() == 1 : "count should be 1";
        assert ua.find(10) == 0 : "10 should be at index 0";
        ua.insert(20);
        ua.insert(30);
        assert ua.count() == 3 : "count should be 3";
        assert ua.find(20) == 1 : "20 should be at index 1";
        assert ua.find(30) == 2 : "30 should be at index 2";
    }

    static void testInsertAtEnd() {
        UnorderedArray ua = new UnorderedArray(5);
        ua.insert(100);
        assert ua.get(0) == 100 : "100 should be at index 0";
        ua.insert(200);
        assert ua.get(1) == 200 : "200 should be at index 1 (inserted at end)";
        ua.insert(300);
        assert ua.get(2) == 300 : "300 should be at index 2";
    }

    static void testInsertAutoResize() {
        UnorderedArray ua = new UnorderedArray(2);
        ua.insert(1);
        ua.insert(2);
        assert ua.size() == 2 : "size should still be 2 before overflow";
        ua.insert(3);
        assert ua.size() == 4 : "size should have doubled to 4";
        assert ua.count() == 3 : "count should be 3";
        assert ua.find(1) != -1 : "1 should still be found";
        assert ua.find(2) != -1 : "2 should still be found";
        assert ua.find(3) != -1 : "3 should be found";
    }

    static void testInsertMultipleAfterResize() {
        UnorderedArray ua = new UnorderedArray(2);
        ua.insert(1);
        ua.insert(2);
        ua.insert(3);
        ua.insert(4);
        ua.insert(5);
        assert ua.size() == 8 : "size should be 8 after two resizes";
        assert ua.count() == 5 : "count should be 5";
        assert ua.find(5) != -1 : "5 should be found";
        assert ua.get(4) == 5 : "5 should be at index 4";
    }

    static void testFullArrayInsertTriggersResize() {
        UnorderedArray ua = new UnorderedArray(2);
        ua.insert(10);
        ua.insert(20);
        assert ua.count() == 2 : "array is full";
        ua.insert(30);
        assert ua.count() == 3 : "count should be 3 after auto-resize";
        assert ua.find(10) != -1 : "10 should still be found";
        assert ua.find(20) != -1 : "20 should still be found";
    }

    // --- Find ---

    static void testFind() {
        UnorderedArray ua = new UnorderedArray(5);
        ua.insert(5);
        ua.insert(3);
        ua.insert(8);
        assert ua.find(5) == 0 : "5 should be at index 0";
        assert ua.find(3) == 1 : "3 should be at index 1";
        assert ua.find(8) == 2 : "8 should be at index 2";
    }

    static void testFindFirstOccurrenceDuplicates() {
        UnorderedArray ua = new UnorderedArray(5);
        ua.insert(7);
        ua.insert(3);
        ua.insert(7);
        ua.insert(7);
        int index = ua.find(7);
        assert index == 0 : "find should return first occurrence at index 0";
        assert ua.count() == 4 : "all duplicates should be stored";
        int index2 = ua.find(3);
        assert index2 == 1 : "3 should be at index 1";
    }

    static void testFindNotFound() {
        UnorderedArray ua = new UnorderedArray(3);
        ua.insert(1);
        assert ua.find(99) == -1 : "99 should not be found";
    }

    static void testFindOnEmptyArray() {
        UnorderedArray ua = new UnorderedArray(3);
        assert ua.find(1) == -1 : "find on empty array should return -1";
    }

    // --- Delete ---

    static void testDeleteFirstElement() {
        UnorderedArray ua = new UnorderedArray(5);
        ua.insert(10);
        ua.insert(20);
        ua.insert(30);
        assert ua.delete(10) : "delete should return true";
        assert ua.count() == 2 : "count should be 2";
        assert ua.find(20) == 0 : "20 should shift to index 0";
        assert ua.find(30) == 1 : "30 should shift to index 1";
    }

    static void testDeleteLastElement() {
        UnorderedArray ua = new UnorderedArray(5);
        ua.insert(10);
        ua.insert(20);
        ua.insert(30);
        assert ua.delete(30) : "delete should return true";
        assert ua.count() == 2 : "count should be 2";
        assert ua.find(30) == -1 : "30 should not be found";
        assert ua.find(10) == 0 : "10 still at index 0";
        assert ua.find(20) == 1 : "20 still at index 1";
    }

    static void testDeleteOnlyElement() {
        UnorderedArray ua = new UnorderedArray(5);
        ua.insert(42);
        assert ua.delete(42) : "delete should return true";
        assert ua.count() == 0 : "count should be 0";
        assert ua.find(42) == -1 : "42 should not be found";
    }

    static void testDeleteNotFound() {
        UnorderedArray ua = new UnorderedArray(3);
        ua.insert(1);
        assert !ua.delete(99) : "delete should return false for non-existent element";
        assert ua.count() == 1 : "count should remain 1";
    }

    static void testDeleteFromEmptyArray() {
        UnorderedArray ua = new UnorderedArray(3);
        assert !ua.delete(1) : "delete on empty array should return false";
        assert ua.count() == 0 : "count should remain 0";
        assert ua.size() == 3 : "size should not change";
    }

    static void testDeleteMultipleInSequence() {
        UnorderedArray ua = new UnorderedArray(10);
        for (int i = 1; i <= 5; i++) ua.insert(i * 10);
        assert ua.delete(30) : "delete 30";
        assert ua.delete(10) : "delete 10";
        assert ua.delete(50) : "delete 50";
        assert ua.count() == 2 : "count should be 2";
        assert ua.find(20) != -1 : "20 should be found";
        assert ua.find(40) != -1 : "40 should be found";
        assert ua.find(10) == -1 : "10 should be gone";
        assert ua.find(30) == -1 : "30 should be gone";
        assert ua.find(50) == -1 : "50 should be gone";
    }

    // --- Get ---

    static void testGet() {
        UnorderedArray ua = new UnorderedArray(5);
        ua.insert(42);
        try {
            assert ua.get(0) == 42 : "get(0) should return 42";
        } catch (IndexOutOfBoundsException e) {
            assert false : "get(0) should not throw";
        }
    }

    static void testGetNullPosition() {
        UnorderedArray ua = new UnorderedArray(5);
        ua.insert(10);
        assert ua.get(0) == 10 : "get(0) should return 10";
        assert ua.get(1) == null : "get(1) should return null (unoccupied per README req 6)";
        assert ua.get(4) == null : "get(4) should return null";
    }

    static void testGetIndexOutOfBoundsNegative() {
        UnorderedArray ua = new UnorderedArray(3);
        ua.insert(1);
        boolean caught = false;
        try { ua.get(-1); } catch (IndexOutOfBoundsException e) { caught = true; }
        assert caught : "get(-1) should throw IndexOutOfBoundsException";
    }

    static void testGetIndexOutOfBoundsLarge() {
        UnorderedArray ua = new UnorderedArray(3);
        ua.insert(1);
        boolean caught = false;
        try { ua.get(5); } catch (IndexOutOfBoundsException e) { caught = true; }
        assert caught : "get(5) should throw IndexOutOfBoundsException";
    }

    static void testGetIndexAtCapacity() {
        UnorderedArray ua = new UnorderedArray(3);
        ua.insert(1);
        boolean caught = false;
        try { ua.get(3); } catch (IndexOutOfBoundsException e) { caught = true; }
        assert caught : "get(capacity=3) should throw IndexOutOfBoundsException";
    }

    // --- Size & Count ---

    static void testSize() {
        UnorderedArray ua = new UnorderedArray(10);
        assert ua.size() == 10 : "size should be 10";
        ua.resize(20);
        assert ua.size() == 20 : "size should be 20 after resize";
    }

    static void testCount() {
        UnorderedArray ua = new UnorderedArray(5);
        assert ua.count() == 0 : "count should be 0 initially";
        ua.insert(1);
        ua.insert(2);
        assert ua.count() == 2 : "count should be 2";
        ua.delete(1);
        assert ua.count() == 1 : "count should be 1 after delete";
    }

    static void testCountAfterMultipleDeletes() {
        UnorderedArray ua = new UnorderedArray(5);
        ua.insert(1);
        ua.insert(2);
        ua.insert(3);
        ua.delete(1);
        ua.delete(2);
        ua.delete(3);
        assert ua.count() == 0 : "count should be 0 after deleting all";
    }

    // --- Resize ---

    static void testResizeExpand() {
        UnorderedArray ua = new UnorderedArray(3);
        ua.insert(100);
        ua.insert(200);
        ua.resize(5);
        assert ua.size() == 5 : "size should be 5";
        assert ua.count() == 2 : "count should still be 2";
        assert ua.find(100) != -1 : "100 should still be found";
        assert ua.find(200) != -1 : "200 should still be found";
        assert ua.get(0) == 100 : "get(0) should be 100";
        assert ua.get(1) == 200 : "get(1) should be 200";
    }

    static void testResizeShrink() {
        UnorderedArray ua = new UnorderedArray(10);
        ua.insert(1);
        ua.insert(2);
        ua.insert(3);
        ua.resize(2);
        assert ua.size() == 2 : "size should be 2";
        assert ua.count() == 2 : "count should be clamped to 2";
        assert ua.find(1) != -1 : "1 should still be found";
        assert ua.find(2) != -1 : "2 should still be found";
        assert ua.find(3) == -1 : "3 should be discarded";
    }

    static void testResizeToZero() {
        UnorderedArray ua = new UnorderedArray(5);
        ua.insert(1);
        ua.insert(2);
        ua.resize(0);
        assert ua.size() == 0 : "size should be 0";
        assert ua.count() == 0 : "count should be clamped to 0";
    }

    static void testResizeToZeroThenInsert() {
        UnorderedArray ua = new UnorderedArray(5);
        ua.insert(1);
        ua.resize(0);
        boolean crashed = false;
        try { ua.insert(2); } catch (ArrayIndexOutOfBoundsException e) { crashed = true; }
        assert crashed : "insert after resize to 0 should crash (size 0 array)";
    }

    static void testResizePreserveOrder() {
        UnorderedArray ua = new UnorderedArray(5);
        ua.insert(1);
        ua.insert(2);
        ua.insert(3);
        ua.resize(4);
        assert ua.get(0) == 1 : "order preserved";
        assert ua.get(1) == 2 : "order preserved";
        assert ua.get(2) == 3 : "order preserved";
    }

    static void testResizeLargerThenSmaller() {
        UnorderedArray ua = new UnorderedArray(3);
        ua.insert(10);
        ua.insert(20);
        ua.resize(10);
        assert ua.size() == 10 : "size should be 10";
        ua.resize(1);
        assert ua.size() == 1 : "size should be 1";
        assert ua.count() == 1 : "count clamped to 1";
        assert ua.find(10) != -1 : "10 preserved";
        assert ua.find(20) == -1 : "20 discarded";
    }

    // --- Delete then Insert ---

    static void testDeleteThenInsert() {
        UnorderedArray ua = new UnorderedArray(5);
        ua.insert(10);
        ua.insert(20);
        ua.delete(10);
        ua.insert(30);
        assert ua.count() == 2 : "count should be 2";
        assert ua.find(20) != -1 : "20 should be found";
        assert ua.find(30) != -1 : "30 should be found";
    }

    static void testInsertAfterDeleteFillsGap() {
        UnorderedArray ua = new UnorderedArray(5);
        ua.insert(10);
        ua.insert(20);
        ua.insert(30);
        ua.delete(20);
        assert ua.count() == 2 : "count should be 2";
        ua.insert(40);
        assert ua.count() == 3 : "count should be 3";
        assert ua.find(40) != -1 : "40 should be found";
        assert ua.find(20) == -1 : "20 should still be gone";
    }

    // --- Empty Array ---

    static void testEmptyArray() {
        UnorderedArray ua = new UnorderedArray(3);
